// What a command gives back. Generated by anything-anything.

/** Text for people, data (JSON-able) for --json and MCP clients, and an exit code. */
export class Output {
  text: string;
  data: unknown;
  exit = 0;

  constructor(text = "", data: unknown = null) {
    this.text = text;
    this.data = data;
  }

  /** Still prints, then exits with this code: for "it worked, and found problems". */
  withExit(code: number): Output {
    this.exit = code;
    return this;
  }

  print(json: boolean): void {
    if (json) {
      process.stdout.write(`${JSON.stringify(this.data ?? { text: this.text }, null, 2)}\n`);
    } else if (this.text) {
      process.stdout.write(`${this.text.replace(/\n+$/, "")}\n`);
    }
  }
}
